"""Test setup: import path for the scripts and a synthetic take generated by ffmpeg."""

from __future__ import annotations

import shutil
import subprocess
import sys
from pathlib import Path

import pytest

SCRIPTS = Path(__file__).resolve().parents[1] / "scripts"
sys.path.insert(0, str(SCRIPTS))

from common import Word, WordsFile, load_words  # noqa: E402

HAVE_FFMPEG = bool(shutil.which("ffmpeg") and shutil.which("ffprobe"))
NEED_FFMPEG = pytest.mark.skipif(not HAVE_FFMPEG, reason="ffmpeg/ffprobe not installed")

# The fake take: (text, start) of each phrase; words are 0.4 s long, 0.05 s apart.
# P1 is a false start of P2, P3 is said again as P4, P5 closes. Pauses of 1.6, 0.7, 0.5, 0.5 s.
PHRASE_SPEC: list[tuple[str, float]] = [
    ("сегодня я расскажу", 0.8),
    ("сегодня я расскажу про монтаж рилсов", 3.6),
    ("это очень просто", 6.7),
    ("это очень просто", 8.5),
    ("и это всё", 10.2),
]
CLIP_DURATION = 13.0

FIXTURES = Path(__file__).resolve().parent / "fixtures"


def real_take() -> WordsFile:
    """Words of a real 62.5 s Russian take as Groq returned them (154 words, drifting times)."""
    return load_words(FIXTURES / "real_take_words.json")


def fake_words() -> list[Word]:
    """Word list that matches the tone bursts of the synthetic clip."""
    words: list[Word] = []
    for text, start in PHRASE_SPEC:
        cursor = start
        for token in text.split():
            words.append(Word(token, round(cursor, 3), round(cursor + 0.35, 3)))
            cursor += 0.4
    return words


def burst_spans() -> list[tuple[float, float]]:
    """Time ranges where the clip carries a tone: one per phrase, from first word to last word end."""
    out = []
    for text, start in PHRASE_SPEC:
        count = len(text.split())
        out.append((start, start + 0.4 * (count - 1) + 0.35 + 0.05))
    return out


def make_clip(path: Path) -> None:
    """Generate a vertical 1080x1920 test pattern with tone bursts separated by digital silence."""
    gate = "+".join(f"between(t,{a:.3f},{b:.3f})" for a, b in burst_spans())
    audio = f"aevalsrc='0.35*sin(2*PI*220*t)*({gate})':s=48000:d={CLIP_DURATION}"
    done = subprocess.run(
        ["ffmpeg", "-y", "-hide_banner", "-nostdin", "-v", "error",
         "-f", "lavfi", "-i", f"testsrc2=size=1080x1920:rate=30:duration={CLIP_DURATION}",
         "-f", "lavfi", "-i", audio,
         "-c:v", "libx264", "-pix_fmt", "yuv420p", "-preset", "veryfast", "-c:a", "aac", "-b:a", "128k",
         "-shortest", str(path)],
        capture_output=True, text=True, check=False,
    )
    if done.returncode != 0:
        raise RuntimeError(f"cannot generate the test clip: {done.stderr[-500:]}")


@pytest.fixture(scope="session")
def synthetic_clip(tmp_path_factory: pytest.TempPathFactory) -> Path:
    """The synthetic take as an mp4 file (skips the test when ffmpeg is missing)."""
    if not HAVE_FFMPEG:
        pytest.skip("ffmpeg/ffprobe not installed")
    path = tmp_path_factory.mktemp("clip") / "take.mp4"
    make_clip(path)
    return path
